<template>
    <navigation/>
    <div  v-if="$store.state.admin.length !== 0">

        <div class="table-responsive">
           <!-- Button trigger modal -->
   <button type="button" class="btn btn-dark" data-bs-toggle="modal" data-bs-target="#exampleModal">
   Add
   </button>
   
   <!-- Modal -->
   <div class="modal fade" id="exampleModal" tabindex="-1" aria-labelledby="exampleModalLabel" aria-hidden="true">
     <div class="modal-dialog">
       <div class="modal-content">
         <div class="modal-header">
           <h1 class="modal-title fs-5" id="exampleModalLabel">Modal title</h1>
           <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
         </div>
         <div class="modal-body">
           <input id="input" type="text" placeholder="productname" v-model="prodName">
           <input id="input" type="number" placeholder="quantity" v-model="quantity">
           <input id="input" type="number" placeholder="amount" v-model="amount">
           <input id="input" type="text" placeholder="decripstion" v-model="description">
           <input id="input" type="text" placeholder="category" v-model="category">
           <input id="input" type="text" placeholder="img" v-model="img">
         </div>
         <div class="modal-footer">
           <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Close</button>
           <button type="button" class="btn btn-primary" @click="addproducts()">Save changes</button>
         </div>
       </div>
     </div>
   </div>
                           <table class="table table-bordered table-hover table-dark">
                               <thead>
                                   <tr>
                                       <th>prodName</th>
                                       <th>quantity</th>
                                       <th>amount</th>
                                       <th>description</th>
                                       <th>Category</th>
                                       <th>img</th>
                                       <th>edit</th>
                                       <th>delete</th>
                                   </tr>
                               </thead>
                               <tbody>
                                   <tr v-for="item in $store.state.admin" :key="item.id">
                                       <td>{{ item.prodName }}</td>
                                       <td>{{ item.quantity }}</td>
                                       <td>R{{ item.amount }}</td>
                                       <td>{{ item.description }}</td>
                                       <td>{{ item.category }}</td>
                                       <td><img :src="item.img" alt="Product Image" id="image" class=" img-fluid"></td>
                                       <td>
                                                                                   <!-- Button trigger modal -->
                                           <button type="button" class="btn btn-dark" data-bs-toggle="modal" :data-bs-target="'#exampleModal'+item.id">
                                           edit
                                           </button>
   
                                           <!-- Modal -->
                                           <div class="modal fade" :id="'exampleModal'+item.id" tabindex="-1" aria-labelledby="exampleModalLabel" aria-hidden="true">
                                           <div class="modal-dialog">
                                               <div class="modal-content">
                                               <div class="modal-header">
                                                   <h1 class="modal-title fs-5" id="exampleModalLabel">Modal title</h1>
                                                   <button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="Close"></button>
                                               </div>
                                               <div class="modal-body">
                                                   <input id="input" type="text" placeholder="productname" v-model="prodName">
                                                   <input id="input" type="number" placeholder="quantity" v-model="quantity">
                                                   <input id="input" type="number" placeholder="amount" v-model="amount">
                                                   <input id="input" type="text" placeholder="decripstion" v-model="description">
                                                   <input id="input" type="text" placeholder="category" v-model="category">
                                                   <input id="input" type="text" placeholder="img" v-model="img">
                                               </div>
                                               <div class="modal-footer">
                                                   <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Close</button>
                                                   <button type="button" class="btn btn-primary" @click="updateproduct(item.id)">Save changes</button>
                                               </div>
                                               </div>
                                           </div>
                                           </div>
   
                                       </td>
                                       <td><button class="btnes" @click="deleteproducts(item.id)">delete</button></td>
                                   </tr>
                               </tbody>
                           </table>
                       </div>
                    </div>

                    <div v-else>
                      <spinner/>
                    </div>
<footers/>
</template>
<script>
import spinner from '@/components/spinner.vue';
import navigation from '@/components/navigation.vue';
import footers   from '@/components/footers.vue'
import Swal from 'sweetalert2';
export default {
    components:{
        spinner,
        navigation,
        footers
    },
    data(){
        return{
            prodName:'',
            quantity:'',
            amount:'',
            description:'',
            category:'',
            img:''
        }
    },
     methods:{
        async getadmin() {
            await this.$store.dispatch('getadmin');
        },
        async addproducts(){
             this.$store.dispatch('addproducts',this.$data);

        },
        deleteproducts(id) {
            Swal.fire({
  title: "Are you sure?",
  text: "You won't be able to revert this!",
  icon: "warning",
  showCancelButton: true,
  confirmButtonColor: "#3085d6",
  cancelButtonColor: "#d33",
  confirmButtonText: "Yes, delete it!"
}).then((result) => {
  if (result.isConfirmed) {
    Swal.fire({
      title: "Deleted!",
      text: "Your file has been deleted.",
      icon: "success"
    });
    this.$store.dispatch('deleteproducts', id)
    setTimeout(() => {
                        
                        window.location.reload();
                    }, 1500);
  }
});
 
            // this.$store.dispatch('deleteproducts', id)
        },
        updateproduct(id){
    let edit = {
        id: id,
        prodName: this.prodName,
        quantity: this.quantity,
        amount: this.amount,
        description: this.description,
        category: this.category,
        img: this.img
    };

    Swal.fire({
        title: "Do you want to save the changes?",
        showDenyButton: true,
        showCancelButton: true,
        confirmButtonText: "Save",
        denyButtonText: `Don't save`
    }).then((result) => {
        if (result.isConfirmed) {
            this.$store.dispatch('updateproduct', edit)
                .then(() => {
                    Swal.fire("Saved!", "", "success");
                    setTimeout(() => {
                        
                        window.location.reload();
                    }, 1500);
                })
                .catch((error) => {
                    Swal.fire("Error!", error.message, "error");
                });
        } else if (result.isDenied) {
            Swal.fire("Changes are not saved", "", "info");
            setTimeout(() => {
                        
                        window.location.reload();
                    }, 1500);
        }
    }); 
}

    },
    mounted(){
        this.getadmin();
    }
}
</script>
<style>
  body{
    background-color: #363636 !important;
  }
      #image{
        width: 100%;
        object-fit:contain;
        height: 175px
    } 
    td{
        vertical-align: middle
        ;
    }
 
</style>